tl.to('#bg2',{opacity:0,duration:0.6},9.4)
tl.to('#bg3',{opacity:1,duration:0.6,ease:'power2.inOut'},9.4)
tl.set('#s3',{visibility:'visible'},9.4)
tl.to('#s3',{opacity:1,duration:0.55,ease:'power2.out'},9.4)
